//! Isolated writer admission regressions; NativeApp batch-pause acceptance is
//! separate. Only preparation records are seeded; pause/ticks use real handlers.
use super::*;
use artex_domain::Planner;
use std::time::Duration;

struct Fixture {dir:tempfile::TempDir,router:Router,tasks:Vec<String>,runtimes:Vec<String>,run:String}
fn fixture()->Fixture {
    let (dir,mut router,run,mut context)=crate::regression::seeded();router.native_mode=true;context.actor.kind="user".into();context.actor.agent_id=None;context.actor.run_id=None;context.conversation_id=None;
    let bootstrap=artex_domain::bootstrap_plan(&router.snapshot().unwrap(),&context).unwrap();router.internal_commit(bootstrap).unwrap();
    let mut tasks=Vec::new();for name in ["clock-target-one","clock-target-two","independent-clock"] {let plan=artex_domain::plan("task.create",&json!({"description":name,"goal":"Isolated clock fixture","seed_first_intent":false,"timeout_seconds":60}),&router.snapshot().unwrap(),&context).unwrap();tasks.push(router.internal_commit(plan).unwrap()["task_id"].as_str().unwrap().to_owned());}
    let snapshot=router.snapshot().unwrap();let mut p=Planner::new(&snapshot,"fixture.running_tasks",&json!({}));let clock=artex_platform::active_clock_ms().unwrap();let mut runtimes=Vec::new();
    for task in &tasks {let mut d=snapshot.get("tasks",task).unwrap().data.clone();d["status"]=json!("running");d["paused"]=json!(false);d["queued"]=json!(false);p.put("tasks",task,d);let runtime=snapshot.records("task_runtime").into_iter().find(|r|r.data["task_id"]==*task).unwrap();let mut d=runtime.data.clone();d["last_active_clock"]=json!(clock.saturating_sub(1500).to_string());p.put("task_runtime",&runtime.header.id,d);runtimes.push(runtime.header.id.clone());}
    let mut data=snapshot.get("agent_runs",&run).unwrap().data.clone();data["task_id"]=json!(tasks[0]);data["conversation_id"]=Value::Null;p.put("agent_runs",&run,data);router.internal_commit(p.done(json!({}))).unwrap();Fixture{dir,router,tasks,runtimes,run}
}
fn wire(router:&Router,request:&DispatchRequest)->Value {json!({"jsonrpc":"2.0","protocol":"artex-rpc/1.0","id":new_id("request"),"method":request.method,"workspace_id":router.snapshot().unwrap().workspace_id,"engine_epoch":router.engine_epoch,"command_id":request.command_id,"expected":request.expected,"timeout_ms":5000,"params":request.params})}
fn prepared(f:&mut Fixture)->DispatchRequest {
    let params=json!({"taskIds":[f.tasks[0],f.tasks[1],new_id("task")],"action":"pause"});let response=f.router.response(json!({"jsonrpc":"2.0","protocol":"artex-rpc/1.0","id":new_id("request"),"method":"command.prepare","workspace_id":f.router.snapshot().unwrap().workspace_id,"engine_epoch":f.router.engine_epoch,"command_id":null,"expected":[],"timeout_ms":5000,"params":{"method":"ui.controlTasksBatch","params":params}}));assert!(response.get("error").is_none(),"{response}");
    DispatchRequest{id:new_id("request"),method:"ui.controlTasksBatch".into(),workspace_id:Some(f.router.snapshot().unwrap().workspace_id.clone()),engine_epoch:Some(f.router.engine_epoch.clone()),command_id:Some(new_id("command")),expected:serde_json::from_value(response["result"]["expected"].clone()).unwrap(),timeout_ms:5000,params}
}
fn submit(f:&mut Fixture,r:&DispatchRequest)->Value {f.router.response(wire(&f.router,r))}
fn tick(f:&mut Fixture,r:&DispatchRequest) {
    let tasks=f.tasks.iter().map(|id|f.router.snapshot().unwrap().get("tasks",id).unwrap().clone()).collect::<Vec<_>>();f.router.account_task_time().unwrap();let s=f.router.snapshot().unwrap();for task in tasks {assert_eq!(s.get("tasks",&task.header.id).unwrap(),&task,"A non-expiring accounting tick must not change user task versions");}for id in &f.runtimes[..2] {let old=r.expected.iter().find(|e|e.collection=="task_runtime"&&e.id==*id).unwrap();assert_ne!(old.version,s.get("task_runtime",id).unwrap().header.version);}
}
fn unchanged(f:&Fixture,before:&Snapshot) {assert_eq!(f.router.snapshot().unwrap().commit_seq,before.commit_seq);for id in &f.tasks {assert_eq!(f.router.snapshot().unwrap().get("tasks",id),before.get("tasks",id));}for id in &f.runtimes {assert_eq!(f.router.snapshot().unwrap().get("task_runtime",id),before.get("task_runtime",id));}}
fn edit(f:&mut Fixture,collection:&str,id:&str,key:&str,value:Value) {let s=f.router.snapshot().unwrap();let mut p=Planner::new(&s,"fixture.concurrent_user_change",&json!({}));let mut data=s.get(collection,id).unwrap().data.clone();data[key]=value;p.put(collection,id,data);f.router.internal_commit(p.done(json!({}))).unwrap();}

#[test]
fn task_clock_pause_admits_real_tick_preserves_budget_partial_results_reopens_and_replays() {
    let mut f=fixture();let request=prepared(&mut f);tick(&mut f,&request);let before=f.router.snapshot().unwrap();let result=submit(&mut f,&request);assert!(result.get("error").is_none(),"{result}");let items=result["result"]["items"].as_array().unwrap();assert_eq!(items.len(),3);assert_eq!(items[0]["ok"],true);assert_eq!(items[1]["ok"],true);assert_eq!(items[2]["ok"],false);let snapshot=f.router.snapshot().unwrap();
    assert_eq!(snapshot.get("tasks",&f.tasks[2]).unwrap(),before.get("tasks",&f.tasks[2]).unwrap());assert_eq!(snapshot.get("task_runtime",&f.runtimes[2]).unwrap(),before.get("task_runtime",&f.runtimes[2]).unwrap());assert_eq!(snapshot.get("agent_runs",&f.run).unwrap().data["state"],"cancelled");
    for (task,id) in f.tasks[..2].iter().zip(&f.runtimes[..2]) {assert_eq!(snapshot.get("tasks",task).unwrap().data["status"],"paused");let runtime=snapshot.get("task_runtime",id).unwrap();let old=before.get("task_runtime",id).unwrap();assert!(parse_u64(runtime.data["active_elapsed_ms"].as_str().unwrap()).unwrap()>=parse_u64(old.data["active_elapsed_ms"].as_str().unwrap()).unwrap());let elapsed=parse_u64(runtime.data["active_elapsed_ms"].as_str().unwrap()).unwrap();let remaining=parse_u64(runtime.data["remaining_timeout_ms"].as_str().unwrap()).unwrap();assert_eq!(elapsed+remaining,60000);assert_eq!(runtime.data["last_active_clock"],Value::Null);assert_eq!(runtime.data["accounting_state"],"known");}
    let receipt=snapshot.records("command_receipts").into_iter().find(|r|r.data["command_id"]==*request.command_id.as_ref().unwrap()).unwrap().clone();assert_eq!(receipt.data["normalized_params"][CLOCK_ADMISSION_KEY].as_array().unwrap().len(),2);assert!(request.params.get(CLOCK_ADMISSION_KEY).is_none());assert_eq!(Router::task_clock_receipt_matches(&receipt,&request).unwrap(),Some(true));assert_eq!(f.router.repeated(&request).unwrap(),Some(result["result"].clone()));
    std::thread::sleep(Duration::from_millis(1100));f.router.account_task_time().unwrap();let seq=f.router.snapshot().unwrap().commit_seq;assert!(seq>snapshot.commit_seq);let replay=submit(&mut f,&request);assert!(replay.get("error").is_none(),"Actual replay: {replay}");assert_eq!(replay["result"],result["result"]);assert_eq!(f.router.snapshot().unwrap().commit_seq,seq,"Replay cannot repeat pause/cancellation/accounting effects");
    f.router.store.as_mut().unwrap().checkpoint().unwrap();f.router.store.take();f.router.store=Some(Store::open(&f.dir.path().join("store")).unwrap());assert_eq!(submit(&mut f,&request)["result"],result["result"]);assert_eq!(f.router.snapshot().unwrap().commit_seq,seq);
    // A durable acknowledgement must not depend on current live target state.
    let task=f.tasks[0].clone();edit(&mut f,"tasks",&task,"deleted_at",json!(artex_core::now()));assert_eq!(submit(&mut f,&request)["result"],result["result"]);
}
#[test]
fn task_clock_stable_task_run_paused_and_recovery_changes_reject_entire_batch() {
    for case in ["task","run","paused-runtime","recovery"] {
        let mut f=fixture();if case=="paused-runtime" {let task=f.tasks[0].clone();edit(&mut f,"tasks",&task,"status",json!("paused"));edit(&mut f,"tasks",&task,"paused",json!(true));}
        let request=prepared(&mut f);let task=f.tasks[0].clone();let runtime=f.runtimes[0].clone();let run=f.run.clone();match case {"task"=>edit(&mut f,"tasks",&task,"description",json!("Changed by user")),"run"=>edit(&mut f,"agent_runs",&run,"state",json!("waiting")),"paused-runtime"=>edit(&mut f,"task_runtime",&runtime,"active_elapsed_ms",json!("1")),_=>edit(&mut f,"task_runtime",&runtime,"accounting_state",json!("recovery_required"))};let before=f.router.snapshot().unwrap();let result=submit(&mut f,&request);assert_eq!(result["error"]["data"]["code"],"VERSION_CONFLICT","{case}: {result}");unchanged(&f,&before);
    }
}
#[test]
fn task_clock_missing_foreign_future_runtime_and_extra_data_are_not_admitted() {
    for case in ["missing","foreign","future","zero","extra-data","resume"] {
        let mut f=fixture();let mut request=prepared(&mut f);tick(&mut f,&request);match case {"missing"=>request.expected.retain(|e|e.id!=f.runtimes[0]),"foreign"=>{let foreign=f.router.snapshot().unwrap().get("task_runtime",&f.runtimes[2]).unwrap().clone();let e=request.expected.iter_mut().find(|e|e.id==f.runtimes[0]).unwrap();e.id=foreign.header.id;e.version=foreign.header.version;},"future"=>request.expected.iter_mut().find(|e|e.id==f.runtimes[0]).unwrap().version=u64::MAX.to_string(),"zero"=>request.expected.iter_mut().find(|e|e.id==f.runtimes[0]).unwrap().version="0".into(),"resume"=>request.params["action"]=json!("resume"),_=>{}};
        let before=f.router.snapshot().unwrap();if case=="extra-data" {let context=Context{actor:Actor{kind:"user".into(),agent_id:None,run_id:None,engine_epoch:f.router.engine_epoch.clone()},task_id:None,intent_id:None,conversation_id:None};let mut batch=facade::plan(&request.method,&request.params,&before,&context).unwrap();artex_domain::augment_expected(&mut batch,&before).unwrap();for change in &mut batch.changes {if let Change::Put{collection,id,data}=change {if collection=="task_runtime"&&id==&f.runtimes[0] {data["remaining_timeout_ms"]=json!("99999");}}}assert_eq!(f.router.commit(&request,&mut batch).unwrap_err().code,"VERSION_CONFLICT");} else {let result=submit(&mut f,&request);assert_eq!(result["error"]["data"]["code"],"VERSION_CONFLICT","{case}: {result}");}unchanged(&f,&before);
    }
}
#[test]
fn task_clock_receipt_normalizes_only_marked_versions_and_rejects_corrupt_or_changed_intent() {
    let mut f=fixture();let request=prepared(&mut f);tick(&mut f,&request);assert!(submit(&mut f,&request).get("error").is_none());let s=f.router.snapshot().unwrap();let receipt=s.records("command_receipts").into_iter().find(|r|r.data["command_id"]==*request.command_id.as_ref().unwrap()).unwrap().clone();
    for case in ["params","id","stable-version","order","clock-zero","clock-future"] {let mut changed=request.clone();match case {"params"=>changed.params["action"]=json!("resume"),"id"=>changed.expected.iter_mut().find(|e|e.collection=="task_runtime").unwrap().id=new_id("taskruntime"),"order"=>changed.expected.reverse(),"clock-zero"=>changed.expected.iter_mut().find(|e|e.collection=="task_runtime").unwrap().version="0".into(),"clock-future"=>changed.expected.iter_mut().find(|e|e.collection=="task_runtime").unwrap().version=u64::MAX.to_string(),_=>changed.expected.iter_mut().find(|e|e.collection=="tasks").unwrap().version="0".into()};assert_eq!(f.router.repeated(&changed).unwrap_err().code,"COMMAND_ID_REUSE", "{case}");}
    for marker in [json!("bad"),json!([]),json!([f.runtimes[0],f.runtimes[0]]),json!([new_id("taskruntime")]),json!([f.tasks[0]])] {let mut corrupt=receipt.clone();corrupt.data["normalized_params"][CLOCK_ADMISSION_KEY]=marker;assert_eq!(Router::task_clock_receipt_matches(&corrupt,&request).unwrap_err().code,"CORRUPT_STORE");}
    for version in ["0","not-a-version"] {let mut corrupt=receipt.clone();let id=corrupt.data["normalized_params"][CLOCK_ADMISSION_KEY][0].as_str().unwrap().to_owned();let expected=corrupt.data["expected"].as_array_mut().unwrap().iter_mut().find(|e|e["collection"]=="task_runtime"&&e["id"]==id).unwrap();expected["version"]=json!(version);assert_eq!(Router::task_clock_receipt_matches(&corrupt,&request).unwrap_err().code,"CORRUPT_STORE");}
    let mut legacy=receipt.clone();legacy.data["normalized_params"].as_object_mut().unwrap().remove(CLOCK_ADMISSION_KEY);assert_eq!(Router::task_clock_receipt_matches(&legacy,&request).unwrap(),None);let mut old=fixture();let original=prepared(&mut old);assert!(submit(&mut old,&original).get("error").is_none());let receipt=old.router.snapshot().unwrap().records("command_receipts").into_iter().find(|r|r.data["command_id"]==*original.command_id.as_ref().unwrap()).unwrap().clone();assert!(receipt.data["normalized_params"].get(CLOCK_ADMISSION_KEY).is_none());let mut changed=original.clone();changed.expected.iter_mut().find(|e|e.collection=="task_runtime").unwrap().version="0".into();assert_eq!(old.router.repeated(&changed).unwrap_err().code,"COMMAND_ID_REUSE","Receipts without admission metadata keep the original strict dependency comparison");
    let contract=artex_core::contracts::read("rpc.v1.schema.json");artex_core::validate_contract(&contract["methods"]["ui.controlTasksBatch"],&contract,&request.params).unwrap();let mut injected=request.params.clone();injected[CLOCK_ADMISSION_KEY]=json!(f.runtimes);assert!(artex_core::validate_contract(&contract["methods"]["ui.controlTasksBatch"],&contract,&injected).is_err(),"Reserved admission metadata is not a user parameter");
}
